12.1. TIPO ABSTRATO DE DADOS CONJUNTO 293
function pertence (x: longint; c: conjunto): boolean;
(∗ Retorna true se x pertence ao conjunto c e false caso contrario. ∗)
begin
pertence:= busca_binaria (x,c) <> 0;
end;
